/// <summary>
/// Extension of formDataSource DirPartyTable in form DirPartyLookup
/// </summary>
[ExtensionOf(formDataSourceStr(DirPartyLookup, DirPartyTable))]
final class AVADirPartyLookup_DirPartyTableDS_Extension
{
}

Method.Source:
/// <summary>
/// Extension of executeQuery method()
/// </summary>
public void executeQuery()
{
    this.avaEnableEntityTypeFilters();

    next executeQuery();
}

/// <summary>
/// Enables EntityTypeFilters for dirPartyLookup under certain circumstances
/// </summary>
public void avaEnableEntityTypeFilters()
{
    str avaFirstNameControlName = 'Name_FirstName';
    str avaLastNameControlName  = 'Name_LastName';
    str avaFormName             = 'DirPartyQuickCreateForm';
    #define.childToParentCtrl('ChildToParentGroupChildName')
    #define.custTableFrm('CustTable')
    #define.parentToChildCtrl('ChildToParentGroupParentName')
    #define.smmBusRelTable('smmBusRelTable')
    #define.dirpartytable('dirPartyTable')

    DirPartyLookupEntitiesFilter    avaDirPartyLookupEntitiesFilter = element.dirPartyLookupEntitiesFilter;
    FormControl                     avaCallerFormControl            = element.args().callerFormControl();

    if(avaDirPartyLookupEntitiesFilter.parmFilterRelationshipType() != ''
        && element.callerForm.name()        == avaFormName
        && (avaCallerFormControl.name()     == avaFirstNameControlName
            || avaCallerFormControl.name()  == avaLastNameControlName))

    {
        avaDirPartyLookupEntitiesFilter.parmDisableAllEntityTypeFilters(NoYes::No);
    }

    if((element.callerForm.name() ==  #CustTableFrm  || element.callerForm.name() ==  #smmBusRelTable || element.callerForm.name() == #dirPartyTable)
        && (avaCallerFormControl.name() == #childToParentCtrl || avaCallerFormControl.name() == #parenttochildCtrl))
    {
        avaDirPartyLookupEntitiesFilter.parmDisableAllEntityTypeFilters(NoYes::No);
    }

}
